/// <summary>
/// Adding code to Init for FormRun() to inject JS whenever any D365 form opened - Created by Sankar - 29/6/2021
/// </summary>
[ExtensionOf(classStr(FormRun))]
final class DAXVFormRun_Extension
{
}

Method.Source:
    public void init()
    {
        next init();
        
        DAXVWalkMeParameters DAXVWalkMeParameters = DAXVWalkMeParameters::find();
          
        
        if (DAXVWalkMeParameters.IsEnabled && DAXVWalkMeParameters.DAXVGUID)
        {
            str env = '' ; // variable to get the environment details

            if(DAXVWalkMeParameters.CustomEnvironment && DAXVWalkMeParameters.DAXVGUID )
                env = "/" + DAXVWalkMeParameters.CustomEnvironment; // Custom environment we need to assign
            else if(DAXVWalkMeParameters.IsTestEnvironment)
                env = "/test"; // for sandbox we are assigning

            //Concatinating the Environment name with  Guid and environment name
            str url = strFmt('https://cdn.walkme.com/users/%1%2/walkme_%1_https.js', DAXVWalkMeParameters.DAXVGUID, env);


            if(!this.design().controlName("DAXVWalkMeControl"))
            {
                DAXVWalkMeControl control = this.design().addControlEx(classStr(DAXVWalkMeControl), 'DAXVWalkMeControl');
                control.parmURL(url); // Assign the js url
            }
        }
    }
